import React, { useState, useEffect } from "react";
import { sendRequest } from "./requests/requests";
import "./App.css";

function App() {
  const [imageFile, setImageFile] = useState(null);
  const [secondImage, setSecondImage] = useState(null);
  const [operation, setOperation] = useState("gray");
  const [params, setParams] = useState({});
  const [resultUrl, setResultUrl] = useState("");
  const [previewUrl, setPreviewUrl] = useState("");
  const [previewSecond, setPreviewSecond] = useState("");

  useEffect(() => {
    const defaults = {
      binary: { threshold: 127 },
      rotate: { angle: 90 },
      zoom: { scale: 1.2 },
      contrast: { factor: 0.5 },
      median: { kernel_size: 3 },
      motion: { kernel_size: 3 },
      color: { mode: "HSV" },
      double_threshold: { low_thresh: 50, high_thresh: 150 },
      edge: { threshold1: 100, threshold2: 200 },
      crop: { x: 0, y: 0, width: 200, height: 200 },
      noise: { amount: 0.02 },
      denoise: { filter_type: "mean", kernel_size: 3 },
      morphology: { morph_op: "dilate", kernel_size: 3 },
      arithmetic: { arithmetic_op: "subtract" }
    };
    setParams(defaults[operation] || {});
    setSecondImage(null);
    setPreviewSecond("");
    setResultUrl("");
  }, [operation]);

  const handleSubmit = async () => {
    if (!imageFile) {
      alert("Lütfen bir görsel yükleyin.");
      return;
    }
    const data = await sendRequest({
      operation,
      imageFile,
      secondImageFile: secondImage,
      params,
    });
    if (data?.url) {
      setResultUrl(data.url);  // Result URL'den dönen URL'yi state'e alıyoruz
    } else {
      alert("İşlem başarısız oldu.");
      setResultUrl("");
    }
  };

  const handleImageChange = (e) => {
    const file = e.target.files[0];
    setImageFile(file);
    if (file) setPreviewUrl(URL.createObjectURL(file));
  };

  const handleSecondImageChange = (e) => {
    const file = e.target.files[0];
    setSecondImage(file);
    if (file) setPreviewSecond(URL.createObjectURL(file));
  };

  const updateParam = (key, value) => {
    setParams((prev) => ({ ...prev, [key]: value }));
  };

  const renderParams = () => {
    switch (operation) {
      case "binary":
        return <input type="number" className="param-input" value={params.threshold || ""} onChange={(e) => updateParam("threshold", Number(e.target.value))} />;
      case "rotate":
        return <input type="number" className="param-input" value={params.angle || ""} onChange={(e) => updateParam("angle", Number(e.target.value))} />;
      case "zoom":
        return <input type="number" className="param-input" step="0.1" value={params.scale || ""} onChange={(e) => updateParam("scale", Number(e.target.value))} />;
      case "contrast":
        return <input type="number" className="param-input" step="0.1" value={params.factor || ""} onChange={(e) => updateParam("factor", Number(e.target.value))} />;
      case "motion":
      case "median":
        return <input type="number" className="param-input" value={params.kernel_size || ""} onChange={(e) => updateParam("kernel_size", Number(e.target.value))} />;
      case "color":
        return (
          <select className="param-input" value={params.mode || "HSV"} onChange={(e) => updateParam("mode", e.target.value)}>
            <option value="HSV">HSV</option>
            <option value="YUV">YUV</option>
            <option value="LAB">LAB</option>
          </select>
        );
      case "double_threshold":
        return (
          <div className="param-group">
            <input type="number" className="param-input" value={params.low_thresh || ""} onChange={(e) => updateParam("low_thresh", Number(e.target.value))} />
            <input type="number" className="param-input" value={params.high_thresh || ""} onChange={(e) => updateParam("high_thresh", Number(e.target.value))} />
          </div>
        );
      case "edge":
        return (
          <div className="param-group">
            <input type="number" className="param-input" value={params.threshold1 || ""} onChange={(e) => updateParam("threshold1", Number(e.target.value))} />
            <input type="number" className="param-input" value={params.threshold2 || ""} onChange={(e) => updateParam("threshold2", Number(e.target.value))} />
          </div>
        );
      case "crop":
        return (
          <div className="param-group">
            <input type="number" className="param-input" value={params.x || ""} onChange={(e) => updateParam("x", Number(e.target.value))} />
            <input type="number" className="param-input" value={params.y || ""} onChange={(e) => updateParam("y", Number(e.target.value))} />
            <input type="number" className="param-input" value={params.width || ""} onChange={(e) => updateParam("width", Number(e.target.value))} />
            <input type="number" className="param-input" value={params.height || ""} onChange={(e) => updateParam("height", Number(e.target.value))} />
          </div>
        );
      case "noise":
        return <input type="number" step="0.01" className="param-input" value={params.amount || ""} onChange={(e) => updateParam("amount", Number(e.target.value))} />;
      case "denoise":
        return (
          <div className="param-group">
            <select className="param-input" value={params.filter_type || "mean"} onChange={(e) => updateParam("filter_type", e.target.value)}>
              <option value="mean">Mean</option>
              <option value="median">Median</option>
            </select>
            <input type="number" className="param-input" value={params.kernel_size || ""} onChange={(e) => updateParam("kernel_size", Number(e.target.value))} />
          </div>
        );
      case "morphology":
        return (
          <div className="param-group">
            <select className="param-input" value={params.morph_op || "dilate"} onChange={(e) => updateParam("morph_op", e.target.value)}>
              <option value="dilate">Genişlet</option>
              <option value="erode">Aşındır</option>
              <option value="open">Açma</option>
              <option value="close">Kapama</option>
            </select>
            <input type="number" className="param-input" value={params.kernel_size || ""} onChange={(e) => updateParam("kernel_size", Number(e.target.value))} />
          </div>
        );
      case "arithmetic":
        return (
          <div className="param-group">
            <input type="file" className="param-input" onChange={handleSecondImageChange} />
            <select className="param-input" value={params.arithmetic_op || "subtract"} onChange={(e) => updateParam("arithmetic_op", e.target.value)}>
              <option value="subtract">Çıkarma</option>
              <option value="multiply">Çarpma</option>
            </select>
          </div>
        );
      default:
        return null;
    }
  };

  return (
    <div className="container">
      <h2>Görüntü İşleme Uygulaması</h2>
      <input type="file" accept="image/*" onChange={handleImageChange} className="file-input" />
      <select className="dropdown" value={operation} onChange={(e) => setOperation(e.target.value)}>
        <option value="gray">Gri Dönüşüm</option>
        <option value="binary">Binary</option>
        <option value="rotate">Döndürme</option>
        <option value="crop">Kırpma</option>
        <option value="zoom">Yaklaştırma</option>
        <option value="color">Renk Uzamı</option>
        <option value="histogram">Histogram</option>
        <option value="contrast">Kontrast Azalt</option>
        <option value="median">Median</option>
        <option value="double_threshold">Çift Eşik</option>
        <option value="edge">Kenar Bulma</option>
        <option value="noise">Gürültü Ekle</option>
        <option value="denoise">Gürültü Temizle</option>
        <option value="motion">Motion Blur</option>
        <option value="morphology">Morfoloji</option>
        <option value="arithmetic">Aritmetik İşlem</option>
      </select>

      {renderParams()}
      <button onClick={handleSubmit} className="action-button">Uygula</button>

      {operation === "arithmetic" && (previewUrl || previewSecond || resultUrl) && (
        <div className="image-gallery">
          {previewUrl && (
            <div className="image-block">
              <h4>1. Görsel</h4>
              <img src={previewUrl} alt="1. Görsel" className="preview-image" />
            </div>
          )}
          {previewSecond && (
            <div className="image-block">
              <h4>2. Görsel</h4>
              <img src={previewSecond} alt="2. Görsel" className="preview-image" />
            </div>
          )}
          {resultUrl && (
            <div className="image-block">
              <h4>Sonuç</h4>
              <img src={resultUrl} alt="Sonuç" className="preview-image result" onError={(e) => e.target.style.display = 'none'} />
              <a href={resultUrl} download><button className="download-button">İndir</button></a>
            </div>
          )}
        </div>
      )}

      {operation !== "arithmetic" && (previewUrl || resultUrl) && (
        <div className="image-gallery">
          {previewUrl && (
            <div className="image-block">
              <h4>Yüklenen Görsel</h4>
              <img src={previewUrl} alt="Yüklenen" className="preview-image" />
            </div>
          )}
          {resultUrl && (
            <div className="image-block">
              <h4>İşlem Sonucu</h4>
              <img src={resultUrl} alt="Sonuç" className="preview-image result" onError={(e) => e.target.style.display = 'none'} />
              <a href={resultUrl} download><button className="download-button">İndir</button></a>
            </div>
          )}
        </div>
      )}
    </div>
  );
}

export default App;
